        api = container "Order API" "The REST API that validates, persists and processes orders" "Spring Boot" "Service"
        db = container "Order Database" "Stores orders, products and customer data" "PostgreSQL 16" "Database"
        queue = container "Order Events" "Message queue carrying order lifecycle events" "Kafka topic orders.v1" "Queue"
        worker = container "Fulfilment Worker" "Consumes order events and drives fulfilment" "Spring Boot" "Service"
    }
    payments = softwareSystem "Payment Provider" "Third-party payment gateway that authorises and captures card payments" "External"
}
model {
    customer -> web "Browses products and places orders through" "HTTPS"
    support -> api "Looks up and amends orders through" "HTTPS/JSON"
    web -> api "Submits orders and fetches order status" "HTTPS/JSON"
    api -> db "Persists and queries orders" "JDBC/PostgreSQL 16"
    api -> queue "Publishes order lifecycle events to" "Kafka" "Async"
    worker -> queue "Consumes order events from" "Kafka" "Async"
    worker -> db "Updates order fulfilment status" "JDBC/PostgreSQL 16"
    api -> payments "Authorises and captures card payments with" "HTTPS/JSON"
}
views {
    systemLandscape "SystemLandscape" "The landscape of systems that make up the order platform" {
        include *
        autoLayout
        title "Order Platform - System Landscape"
    }

    systemContext orders "SystemContext" "The Order Platform and the people and systems that interact with it" {
        include *
        autoLayout
        title "System Context for Order Platform"
    }

    container orders "Containers" "The containers that make up the Order Platform" {
        include *
        autoLayout
        title "Containers for Order Platform"
    }

    dynamic orders "OrderPlacement" "The sequence of events when a customer places an order" {
        customer -> web "Browses products and places orders through" "HTTPS"
        web -> api "Submits orders and fetches order status" "HTTPS/JSON"
        api -> payments "Authorises and captures card payments with" "HTTPS/JSON"
        api -> db "Persists and queries orders" "JDBC/PostgreSQL 16"
        api -> queue "Publishes order lifecycle events to" "Kafka"
        worker -> queue "Consumes order events from" "Kafka"
        worker -> db "Updates order fulfilment status" "JDBC/PostgreSQL 16"
        autoLayout
        title "Order Placement Flow"
    }
}
views {
    styles {
        element "Person" {
            shape Person
            background #08427B
            color #ffffff
        }
        element "Software System" {
            background #1168BD
            color #ffffff
        }
        element "External" {
            background #999999
            color #ffffff
        }
        element "Container" {
            background #438DD5
            color #ffffff
        }
        element "Component" {
            background #85BBF0
            color #000000
        }
        element "Database" {
            shape Cylinder
        }
        element "Web" {
            shape WebBrowser
        }
        element "Queue" {
            shape Pipe
        }
        relationship "Relationship" {
            routing Orthogonal
        }
        relationship "Async" {
            style dashed
        }
    }
}
}`;
